  string output=Path.Combine(Path.GetDirectoryName(saved),"native-ui-export");var bad=CreatorProject.From(original.Xml());bad.Id=Guid.NewGuid().ToString("N");bad.Voice=Path.Combine(Path.GetDirectoryName(saved),"missing.wav");bad.OutputFolder=output;bad.RequireVietnamese=false;bad.State="QUEUED";bad.Selected=true;bad.Progress.Restore(0,0,false);
